/** ThemeProvider props selecting one generated theme (the other half stays the stock Primer theme). */
export function primerThemeProps(theme: string): Pick<ThemeProviderProps, "colorMode" | "dayScheme" | "nightScheme"> {
  return theme.startsWith("light")
    ? { colorMode: "light", dayScheme: theme, nightScheme: "dark" }
    : { colorMode: "dark", dayScheme: "light", nightScheme: theme };
}

/** Mirror the same choice onto <html>, so the page background and portalled overlays follow. */
export function applyPrimerTheme(theme: string, root: HTMLElement = document.documentElement): void {
  const props = primerThemeProps(theme);
  root.setAttribute("data-color-mode", props.colorMode ?? "dark");
  root.setAttribute("data-light-theme", props.dayScheme ?? "light");
  root.setAttribute("data-dark-theme", props.nightScheme ?? "dark");
}
